		discipline = disciplineRepository.save(new Discipline("Базы данных " + UUID.randomUUID(), department.getId()));
		semesterRepository.save(new Semester("2026/2027 — осенний", LocalDate.of(2026, 9, 1),
				LocalDate.of(2027, 1, 31), true));
		officeBearer = bearer(createUser(uniqueEmail("office"), "office12345", Role.ACADEMIC_OFFICE));
	}

	@Test
	void officeInvitesTeacherAndTeacherAccepts() throws Exception {
		String email = uniqueEmail("teacher");
		CreateTeacherInviteRequest request = new CreateTeacherInviteRequest("Иванов Иван Петрович", email,
				discipline.getDepartmentId(), List.of(discipline.getId()).stream().collect(java.util.stream.Collectors.toSet()),
				java.util.Set.of(group.getId()));

		String body = mockMvc.perform(post("/api/academic/teacher-invites")
						.header("Authorization", officeBearer)
						.contentType(MediaType.APPLICATION_JSON)
						.content(objectMapper.writeValueAsString(request)))
				.andExpect(status().isCreated())
				.andExpect(jsonPath("$.email").value(email))
				.andReturn().getResponse().getContentAsString();

		TeacherInviteCreatedResponse created = objectMapper.readValue(body, TeacherInviteCreatedResponse.class);
		String token = capturedInviteToken(email);

		mockMvc.perform(get("/api/auth/teacher-invites/{token}", token))
				.andExpect(status().isOk())
				.andExpect(jsonPath("$.email").value(email))
				.andExpect(jsonPath("$.fullName").value("Иванов Иван Петрович"));

		mockMvc.perform(post("/api/auth/teacher-invites/{token}/accept", token)
						.contentType(MediaType.APPLICATION_JSON)
						.content(objectMapper.writeValueAsString(new AcceptTeacherInviteRequest("teacher12345"))))
				.andExpect(status().isCreated())
				.andExpect(jsonPath("$.accessToken").isNotEmpty())
				.andExpect(jsonPath("$.role").value("TEACHER"))
				.andExpect(jsonPath("$.userId").isNotEmpty());

		assertThat(userRepository.findByEmailIgnoreCase(email)).isPresent()
				.get().extracting(user -> user.getRole()).isEqualTo(Role.TEACHER);
		assertThat(teacherAssignmentRepository.findGroupIds(
				userRepository.findByEmailIgnoreCase(email).orElseThrow().getId(),
				semesterRepository.findByName("2026/2027 — осенний").orElseThrow().getId(),
				com.ptu.backend.academic.domain.AssignmentStatus.ACTIVE))
				.containsExactly(group.getId());
		assertThat(created.expiresAt()).isNotNull();

		mockMvc.perform(get("/api/auth/teacher-invites/{token}", token))
				.andExpect(status().isGone());
	}

	@Test
	void duplicatePendingInviteIsRejected() throws Exception {
		String email = uniqueEmail("teacher");
		String payload = objectMapper.writeValueAsString(new CreateTeacherInviteRequest("Петров Пётр", email,
				discipline.getDepartmentId(), java.util.Set.of(discipline.getId()), java.util.Set.of(group.getId())));

		mockMvc.perform(post("/api/academic/teacher-invites")
						.header("Authorization", officeBearer)
						.contentType(MediaType.APPLICATION_JSON)
						.content(payload))
				.andExpect(status().isCreated());

		mockMvc.perform(post("/api/academic/teacher-invites")
						.header("Authorization", officeBearer)
						.contentType(MediaType.APPLICATION_JSON)
						.content(payload))
				.andExpect(status().isConflict());
	}

	@Test
	void teacherCannotCreateInvites() throws Exception {
		String teacherBearer = bearer(createUser(uniqueEmail("teacher"), "teacher12345", Role.TEACHER));
		String payload = objectMapper.writeValueAsString(new CreateTeacherInviteRequest("Сидоров Сидор",
				uniqueEmail("invited"), discipline.getDepartmentId(), java.util.Set.of(discipline.getId()),
				java.util.Set.of(group.getId())));

		mockMvc.perform(post("/api/academic/teacher-invites")
						.header("Authorization", teacherBearer)
						.contentType(MediaType.APPLICATION_JSON)
						.content(payload))
				.andExpect(status().isForbidden());
	}

	@Test
	void unknownTokenReturnsNotFound() throws Exception {
		mockMvc.perform(get("/api/auth/teacher-invites/{token}", Hashing.randomToken()))
				.andExpect(status().isNotFound());
	}

	private String capturedInviteToken(String email) {
		ArgumentCaptor<String> link = ArgumentCaptor.forClass(String.class);
		verify(mailService).sendTeacherInvite(eq(email), any(), link.capture(), any(Duration.class));
		String query = URI.create(link.getValue()).getQuery();
		assertThat(query).startsWith("token=");
		return java.net.URLDecoder.decode(query.substring("token=".length()), java.nio.charset.StandardCharsets.UTF_8);
	}
}

